1	import React, { useState, useEffect, useCallback } from 'react';
2	import { useNavigate } from 'react-router-dom';
3	import {
4	  listarGarcons, criarGarcom, atualizarGarcom, removerGarcom,
5	  listarMesas, criarMesa, removerMesa, criarMesasEmLote,
6	} from '../../services/restauranteService';
7	import Icon from '../../components/AppIcon';
8	import { useSolicitacoesMotoboyCount } from '../../hooks/useSolicitacoesMotoboyCount';
9	import { useMinhaLojaSlug } from '../../hooks/useMinhaLojaSlug';
10	import { useTipoRestaurante } from '../../hooks/useTipoRestaurante';
11	import RestauranteSidebar from '../../components/restaurante/RestauranteSidebar';
12	
13	const NavRestaurante = ({ active }) => {
14	  const navigate = useNavigate();
15	  const pendentes = useSolicitacoesMotoboyCount();
16	  const slugLoja = useMinhaLojaSlug();
17	  const tipoRestaurante = useTipoRestaurante();
18	  const [sidebarAberto, setSidebarAberto] = useState(false);
19	  const links = [
20	    { label: 'Dashboard', path: '/restaurante' },
21	    { label: 'Relatórios', path: '/restaurante/relatorios' },
22	    { label: 'Delivery', path: '/restaurante/delivery' },
23	    { label: 'Produtos', path: '/restaurante/produtos' },
24	    { label: 'Pedidos', path: '/restaurante/pedidos' },
25	    { label: 'Entregas', path: '/restaurante/entregas' },
26	    { label: 'Motoboys', path: '/restaurante/motoboys' },
27	    ...(tipoRestaurante ? [
28	      { label: 'Salão', path: '/restaurante/salao' },
29	      { label: 'Garçons', path: '/restaurante/garcons' },
30	      { label: 'Impressoras', path: '/restaurante/impressoras' },
31	    ] : []),
32	    { label: 'Clientes', path: '/restaurante/clientes' },
33	    { label: 'Designer', path: '/restaurante/aparencia' },
34	    { label: 'Cardápio Digital', path: '/restaurante/cardapio-digital' },
35	    { label: 'Config', path: '/restaurante/config' },
36	  ];
37	  return (
38	    <>
39	      <nav className="md:hidden flex gap-1.5 flex-wrap">
40	        {links.map((l) => (
41	          <button key={l.path} onClick={() => navigate(l.path)}
42	            className={`relative px-3 py-2 text-sm font-semibold rounded-lg transition-colors ${
43	              active === l.path ? 'text-white bg-[#FF441F] shadow-sm shadow-[#FF441F]/30' : 'text-[#27272A] hover:bg-[#F4F4F5]'
44	            }`}>
45	            {l.label}
46	            {l.path === '/restaurante/motoboys' && pendentes > 0 && (
47	              <span className="absolute -top-1 -right-1 min-w-[18px] h-[18px] px-1 flex items-center justify-center bg-red-500 text-white text-[10px] font-bold rounded-full border-2 border-white">
48	                {pendentes}
49	              </span>
50	            )}
51	          </button>
52	        ))}
53	        {slugLoja && (
54	          <button onClick={() => window.open(`/r/${slugLoja}`, '_blank')}
55	            className="px-3 py-2 text-sm font-semibold rounded-lg text-green-700 bg-green-50 hover:bg-green-100 border border-green-200 flex items-center gap-1.5">
56	            <Icon name="ExternalLink" size={14} /> Loja
57	          </button>
58	        )}
59	      </nav>
60	      <button onClick={() => setSidebarAberto(true)}
61	        className="hidden md:flex items-center gap-2 px-3 py-2 text-sm font-semibold rounded-lg text-[#27272A] hover:bg-[#F4F4F5] border border-[#E4E4E7]">
62	        <Icon name="Menu" size={18} /> Menu
63	      </button>
64	      <RestauranteSidebar
65	        open={sidebarAberto}
66	        onClose={() => setSidebarAberto(false)}
67	        links={links}
68	        activePath={active}
69	        pendentesMotoboy={pendentes}
70	        slugLoja={slugLoja}
71	      />
72	    </>
73	  );
74	};
75	
76	const NovoGarcomForm = ({ onCriado }) => {
77	  const [nome, setNome] = useState('');
78	  const [telefone, setTelefone] = useState('');
79	  const [senha, setSenha] = useState('');
80	  const [erro, setErro] = useState(null);
81	  const [salvando, setSalvando] = useState(false);
82	
83	  const submit = async (e) => {
84	    e.preventDefault();
85	    setErro(null);
86	    setSalvando(true);
87	    try {
88	      await criarGarcom({ nome, telefone, senha });
89	      setNome(''); setTelefone(''); setSenha('');
90	      onCriado();
91	    } catch (err) {
92	      setErro(err.message);
93	    } finally {
94	      setSalvando(false);
95	    }
96	  };
97	
98	  return (
99	    <form onSubmit={submit} className="bg-white rounded-2xl border border-[#E4E4E7] p-4 mb-4 flex flex-wrap gap-2 items-end">
